#!/bin/bashsource /opt/ros/humble/setup.bashsource /home/zyc/gsl_ws/install/setup.bashOUT=/tmp/isj_final_expmkdir -p $OUTCSV=$OUT/all_results.csvecho "method,config,seed,final_error,steps,wall_time,type" > $CSV# Scenarios: CONFIG SX SY SZ STX STY DATAPATHSCENARIOS=(    "2,4-1_fast|-0.40|-2.90|-0.30|-0.90|0.15|/home/zyc/vgr_data_scenarios/House01"    "1,3-2,4_fast|-0.60|1.95|0.40|-0.90|0.15|/home/zyc/vgr_data_scenarios/House01"    "3,5-1_fast|0.00|-1.00|0.20|1.06|-2.50|/home/zyc/vgr_data_scenarios/House02/House02"    "1-2,5_fast|-0.45|1.90|-0.10|2.20|0.49|/home/zyc/vgr_data_scenarios/House03/House03"    "5-3_fast|8.20|5.00|-0.20|5.20|4.99|/home/zyc/vgr_data_scenarios/House03/House03")# Methods: NAME EXTRA_ARGSMETHODS=(    "OPGSL_fixed|algorithm:=OPGSL use_sbd:=false opgsl_ddm:=false opgsl_wraig:=false opgsl_cp:=false opgsl.event_driven.enabled:=true"    "OPGSL_eprocess|algorithm:=OPGSL use_sbd:=false opgsl_ddm:=false opgsl_wraig:=false opgsl_cp:=true opgsl.event_driven.enabled:=true"    "SurgeCast|algorithm:=SurgeCast use_sbd:=false"    "GrGSL|algorithm:=GrGSL use_sbd:=false")SEEDS=10TIMEOUT=180MAX_WAIT=250run_one() {    local method_name=$1 extra_args=$2 config=$3 sx=$4 sy=$5 sz=$6 stx=$7 sty=$8 datapath=$9 seed=${10}    local logfile="$OUT/${config}_${method_name}_s${seed}.log"        if grep -q "${method_name},${config},${seed}," $CSV 2>/dev/null; then        echo "[$(date +%H:%M:%S)] SKIP $method_name $config s$seed"        return 0    fi        echo "[$(date +%H:%M:%S)] $method_name $config s$seed"        local start_time=$(date +%s)        ros2 launch vgr_bridge vgr_ablation.launch.py \        vgr_data_path:=$datapath config_id:=$config \        source_x:=$sx source_y:=$sy source_z:=$sz \        start_x:=$stx start_y:=$sty seed:=$seed \        timeout_sec:=$TIMEOUT resultsFile:=$OUT/null.txt \        $extra_args > $logfile 2>&1 &    local PID=$!        local ELAPSED=0    while [ $ELAPSED -lt $MAX_WAIT ]; do        sleep 5        ELAPSED=$((ELAPSED + 5))        if grep -q "DONE, CLOSING" $logfile 2>/dev/null; then            sleep 3            break        fi        if ! kill -0 $PID 2>/dev/null; then break; fi    done        local end_time=$(date +%s)    local wall_time=$((end_time - start_time))        pkill -9 -f vgr_sim_node 2>/dev/null    pkill -9 -f gsl_actionserver 2>/dev/null    pkill -9 -f benchmark_runner 2>/dev/null    kill -9 $PID 2>/dev/null    sleep 3        local ERROR=$(grep "wrote.*final_error" $logfile | grep -oP 'final_error=\K[0-9.]+')    local STEPS=$(grep "OPGSL-AI step=" $logfile | tail -1 | grep -oP 'step=\K[0-9]+')    [ -z "$STEPS" ] && STEPS=0        if [ -n "$ERROR" ]; then        echo "$method_name,$config,$seed,$ERROR,$STEPS,$wall_time,ok" >> $CSV        echo "  -> ${ERROR}m ${STEPS}steps ${wall_time}s"    else        local RES_ERR=$(grep "RESULT IS:" $logfile | grep -oP 'Search_d=\K[0-9.]+')        if [ -n "$RES_ERR" ]; then            echo "$method_name,$config,$seed,$RES_ERR,$STEPS,$wall_time,result" >> $CSV            echo "  -> ${RES_ERR}m (result)"        else            echo "$method_name,$config,$seed,999,0,$wall_time,failed" >> $CSV            echo "  -> FAILED"        fi    fi}for scenario in "${SCENARIOS[@]}"; do    IFS='|' read -r config sx sy sz stx sty datapath <<< "$scenario"    for method in "${METHODS[@]}"; do        IFS='|' read -r method_name extra_args <<< "$method"        for seed in $(seq 0 $((SEEDS-1))); do            run_one "$method_name" "$extra_args" "$config" "$sx" "$sy" "$sz" "$stx" "$sty" "$datapath" "$seed"        done    donedoneecho ""echo "=== ALL COMPLETE ==="echo "Total runs: $(tail -n +2 $CSV | wc -l)"echo ""echo "=== SUMMARY ==="python3 -c "import csvfrom collections import defaultdictdata = defaultdict(list)with open('$CSV') as f:    reader = csv.DictReader(f)    for row in reader:        try:            data[(row['method'], row['config'])].append(float(row['final_error']))        except:            passfor (m, c), errs in sorted(data.items()):    mean = sum(errs)/len(errs)    std = (sum((e-mean)**2 for e in errs)/len(errs))**0.5    succ = sum(1 for e in errs if e <= 2.0)    print(f'{m:20s} {c:20s} n={len(errs):2d} mean={mean:.2f} std={std:.2f} succ={succ}/{len(errs)}')"